          onMouseEnter={(e) => {
            e.currentTarget.style.backgroundColor = ACCENT_HOVER;
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.backgroundColor = ACCENT;
          }}
        >
          重試
        </button>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6 overflow-y-auto">
      {/* ── 1. Hero — dark gradient + orange glow (tPAAW hero style) ── */}
      <section
        className="rounded-xl p-6 relative overflow-hidden"
        style={{
          background:
            "linear-gradient(135deg, #1c1917 0%, #292524 100%)",
        }}
      >
        {/* Orange glow accent */}
        <div
          className="absolute top-0 right-0 w-64 h-64 rounded-full blur-3xl opacity-20 pointer-events-none"
          style={{ backgroundColor: ACCENT }}
          aria-hidden="true"
        />
        <div className="relative">
          <h1 className="text-xl font-normal text-stone-100">
            🛡️ SRE Agent Platform
          </h1>
          <p className="text-sm text-stone-400 mt-1">
            {crews.length} 位 AI Agent · {tools.length} 個工具 · 自動化事件排查
          </p>
          <div className="flex flex-wrap gap-2 mt-4">
            {QUICK_ACTIONS.map((action) => (
              <button
                key={action.id}
                type="button"
                onClick={() =>
                  onQuickAction
                    ? onQuickAction(action.prompt)
                    : onNavigate("console")
                }
                className="flex items-center gap-1.5 px-3 py-2 text-xs font-medium rounded-lg bg-white/5 border border-white/10 text-stone-300 transition-colors"
                onMouseEnter={(e) => {
                  e.currentTarget.style.borderColor = ACCENT;
                  e.currentTarget.style.backgroundColor = ACCENT_BG;
                  e.currentTarget.style.color = ACCENT_TEXT;
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.borderColor = "";
                  e.currentTarget.style.backgroundColor = "";
                  e.currentTarget.style.color = "#78716c";
                }}
              >
                <span aria-hidden="true">{action.icon}</span>
                {action.label}
              </button>
            ))}
          </div>
        </div>
      </section>

      {/* ── 2. Stats row ── */}
      <section className="grid grid-cols-3 gap-4">
        <StatCard label="AI Agents" value={crews.length} icon="👥" />
        <StatCard label="MCP Tools" value={tools.length} icon="🔧" />
        <StatCard
          label="Uptime"
          value={formatUptime(health?.uptime)}
          icon="⏱️"
        />
      </section>

      {/* ── 3. Agent grid ── */}
      <section>
        <div className="flex items-center justify-between mb-3">
          <h2 className="text-lg font-normal text-stone-800">
            Agent Team
          </h2>
          <button
            type="button"
