            style={{ color: ACCENT }}
            onMouseEnter={(e) => {
              e.currentTarget.style.color = ACCENT_HOVER;
            }}
            onMouseLeave={(e) -> {
              e.currentTarget.style.color = ACCENT;
            }}
          >
            View all →
